-- `ON CONFLICT DO NOTHING` KULLANILMAZ: çakışan bir aday bile TD sayacını
-- tüketir ve defter birkaç haftada boşluklarla dolardı.
with incoming_supplier (name, match_key) as (
  values
    ('AĞIR HADDECİLİK', 'AGIR HADDECILIK'),
    ('ANKARA PROFİL BORU TİCARET VE SANAYİ LTD.ŞTİ.', 'ANKARA PROFIL BORU TICARET VE SANAYI LTD.STI.'),
    ('ARCELORMİTTAL RZK ÇELİK', 'ARCELORMITTAL RZK CELIK'),
    ('AYAZ BORU PROFİL', 'AYAZ BORU PROFIL'),
    ('CECELİ DEMİR', 'CECELI DEMIR'),
    ('DESSAN DEMİR ÇELİK', 'DESSAN DEMIR CELIK'),
    ('EAG DEMİR', 'EAG DEMIR'),
    ('FZK TEKNİK METAL', 'FZK TEKNIK METAL'),
    ('HAKAN SAC METAL', 'HAKAN SAC METAL'),
    ('KARÇEL KARDEMİR ÇELİK', 'KARCEL KARDEMIR CELIK'),
    ('SEÇKİN METAL', 'SECKIN METAL'),
    ('TAŞÇELİK DEMİR ÇELİK', 'TASCELIK DEMIR CELIK'),
    ('ÜNALLAR METAL', 'UNALLAR METAL')
)
insert into public.purchase_suppliers (name, match_key)
select incoming.name, incoming.match_key
from incoming_supplier incoming
where not exists (
  select 1 from public.purchase_suppliers existing
  where existing.match_key = incoming.match_key
);

